#!/bin/sh
# TEMPORARY dev setup: runs once, when the dev server's database volume is first created.
# The same three roles as locally and on Aurora (see docker/postgres-init.sql), with passwords from
# the server's .env (generated by setup-server.sh), and only the helpdesk database.
set -eu

psql -v ON_ERROR_STOP=1 --username postgres --dbname postgres <<SQL
CREATE ROLE helpdesk_migrator LOGIN PASSWORD '${MIGRATOR_DB_PASSWORD}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
CREATE ROLE helpdesk_app      LOGIN PASSWORD '${APP_DB_PASSWORD}'      NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
CREATE ROLE helpdesk_readonly LOGIN PASSWORD '${READONLY_DB_PASSWORD}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
ALTER ROLE helpdesk_readonly SET default_transaction_read_only = on;
CREATE DATABASE helpdesk OWNER helpdesk_migrator;
\connect helpdesk
ALTER SCHEMA public OWNER TO helpdesk_migrator;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
CREATE EXTENSION IF NOT EXISTS pg_stat_statements;
SQL
